mapper.sql:
FROM employee_purchase_activity_goods g
LEFT JOIN items i ON g.goods_id = i.goods_id
LEFT JOIN goods_items_rel_cats c ON i.item_id = c.item_id

	LEFT JOIN distribution_distributor_items di ON i.item_id = di.item_id AND di.is_can_sale = 1


	INNER JOIN employee_purchase_activity_items epai
		ON g.goods_id = epai.goods_id
		AND g.activity_id = epai.activity_id
		AND g.company_id = epai.company_id



		AND g.company_id = #{filter.companyId}


		AND g.activity_id = #{filter.activityId}


		AND epai.shelf_status = #{filter.shelfStatus}


		AND i.item_category IN

			#{id}



		AND c.category_id IN

			#{cid}



		AND i.approve_status IN

			#{st}



		AND di.item_id IS NOT NULL


		AND i.item_name LIKE CONCAT('%', #{filter.itemName}, '%')


		AND i.item_bn = #{filter.itemBn}


		AND (
			i.item_name LIKE CONCAT('%', #{filter.keywords}, '%')
			OR i.item_bn LIKE CONCAT('%', #{filter.keywords}, '%')
		)

	AND i.goods_id IS NOT NULL

mapper.select:
SELECT DISTINCT g.goods_id

ORDER BY g.goods_id DESC
LIMIT #{offset}, #{limit}
